    x += w[i];
  });

  rows.forEach((r, idx) => {
    const y = y0 + h * (idx + 1);
    const fill = idx % 2 === 0 ? 'F7FAFF' : 'EDF3FF';
    let cx = x0;
    [r.date, r.outcome, r.rationale].forEach((txt, i) => {
      slide.addShape(pres.ShapeType.rect, { x: cx, y, w: w[i], h, fill: { color: fill }, line: { color: 'D4DCEC', pt: 0.6 } });
