    { date: 'Day 5', outcome: 'Accepted', rationale: 'Improved failure classification for token-vs-SSH mismatch cases.' },
    { date: 'Day 6', outcome: 'Rejected', rationale: 'Further edits plateaued; no validator gain over current best skill.' }
  ];
  addCaseTable(slide, rows, 3, 6, 'Iterative refinement when evidence supports updates:');
}

