    {
      t: 'Collective evolution',
      d: 'Individual interactions contribute to a shared, continuously improving skill ecosystem.'
    },
    {
      t: 'Fully automatic',
      d: 'Runtime interaction drives skill updates without manual curation or explicit user intervention.'
    },
    {
      t: 'Agentic evolution paradigm',
      d: 'Open-ended reasoning over evidence enables context-aware skill mutations beyond fixed rules.'
    }
  ];

  items.forEach((it, i) => {
    const y = 1.9 + i * 1.1;
    slide.addShape(pres.ShapeType.roundRect, { x: 0.9, y, w: 11.6, h: 0.85, radius: 0.05, fill: { color: 'FFFFFF' }, line: { color: 'CEDCFA', pt: 1 } });
    slide.addShape(pres.ShapeType.ellipse, { x: 1.15, y: y + 0.22, w: 0.38, h: 0.38, fill: { color: theme.accent }, line: { color: theme.accent, pt: 0 } });
    slide.addText(String(i + 1), { x: 1.29, y: y + 0.31, w: 0.1, h: 0.1, fontSize: 10, bold: true, color: 'FFFFFF', align: 'center' });
    slide.addText(it.t, { x: 1.7, y: y + 0.2, w: 3.4, h: 0.25, fontSize: 15, bold: true, color: theme.secondary });
    slide.addText(it.d, { x: 1.7, y: y + 0.47, w: 10.3, h: 0.3, fontSize: 12, color: theme.text });
  });

  slide.addText('Implication: SkillClaw operationalizes continuously improving agent systems by turning distributed user experience into validated shared capabilities.', {
    x: 0.9, y: 5.1, w: 12.0, h: 0.3, fontSize: 11.8, bold: true, color: theme.primary
  });
