function addCaseTable(slide, rows, acceptedCount, totalCount, caption) {
  const x0 = 0.9, y0 = 2.0;
  const w = [1.5, 2.6, 7.9];
  const h = 0.45;
  const headers = ['Date', 'Outcome', 'Rationale'];

  let x = x0;
  headers.forEach((hd, i) => {
    slide.addShape(pres.ShapeType.rect, { x, y: y0, w: w[i], h, fill: { color: '1C2541' }, line: { color: 'FFFFFF', pt: 0.7 } });
    slide.addText(hd, { x: x + 0.05, y: y0 + 0.12, w: w[i] - 0.1, h: 0.2, fontSize: 12, bold: true, color: 'FFFFFF', align: i === 2 ? 'left' : 'center' });
    x += w[i];
  });

  rows.forEach((r, idx) => {
    const y = y0 + h * (idx + 1);
    const fill = idx % 2 === 0 ? 'F7FAFF' : 'EDF3FF';
    let cx = x0;
    [r.date, r.outcome, r.rationale].forEach((txt, i) => {
      slide.addShape(pres.ShapeType.rect, { x: cx, y, w: w[i], h, fill: { color: fill }, line: { color: 'D4DCEC', pt: 0.6 } });
      slide.addText(txt, {
        x: cx + 0.06, y: y + 0.1, w: w[i] - 0.12, h: 0.3,
        fontSize: 11, color: i === 1 ? (txt.includes('Accepted') ? theme.ok : theme.bad) : theme.text,
        bold: i === 1, align: i === 2 ? 'left' : 'center'
      });
      cx += w[i];
    });
  });

  slide.addText(`${caption} Accepted ${acceptedCount}/${totalCount} candidates during 6-day evolution window.`, {
    x: 0.95, y: 5.05, w: 11.8, h: 0.3, fontSize: 11.5, bold: true, color: theme.secondary
  });
}

